    deepExplanation: "Step 1 — Understand the React pattern.\n\nStep 1 — Define the state, action, and default transition.\n\nWITHOUT BUILT-IN / CORE:\n```ts\ninterface CounterState {\n  count: number;\n}\n\ntype CounterAction =\n  | { type: \"increment\" }\n  | { type: \"decrement\" };\n\nfunction defaultReducer(\n  state: CounterState,\n  action: CounterAction,\n): CounterState {\n  if (action.type === \"increment\") {\n    return { count: state.count + 1 };\n  }\n\n  return { count: state.count - 1 };\n}\n\nfunction createCounterReducer(\n  override?: (\n    state: CounterState,\n    action: CounterAction,\n  ) => CounterState,\n) {\n  return (\n    state: CounterState,\n    action: CounterAction,\n  ): CounterState =>\n    override\n      ? override(state, action)\n      : defaultReducer(state, action);\n}\n```\n\nWITH BUILT-IN / customized reducer:\n```ts\ninterface CounterState {\n  count: number;\n}\n\ntype CounterAction =\n  | { type: \"increment\" }\n  | { type: \"decrement\" };\n\nfunction defaultReducer(\n  state: CounterState,\n  action: CounterAction,\n): CounterState {\n  if (action.type === \"increment\") {\n    return { count: state.count + 1 };\n  }\n\n  return { count: state.count - 1 };\n}\n\nfunction limitAtTen(\n  state: CounterState,\n  action: CounterAction,\n): CounterState {\n  const next = defaultReducer(state, action);\n  return { count: Math.min(10, next.count) };\n}\n```\n\nExample:\nA reusable menu has a default reducer but a product can override transitions for custom business behavior.\n\nComplexity:\nA simple reducer transition is O(1).\n\nTrade-off:\nThis pattern is powerful for reusable component libraries but more complex than normal controlled props.\n\nStep 5 — Senior interview takeaway:\nExplain the state ownership, component API, re-render implications, and why a simpler alternative may be better.",
